const std = @import("std");
const C = @import("canvas.zig");
pub fn bresenham(first: C.Point, last: C.Point) []const C.Point {
    var x = first.x; var y = first.y; const dx = C.abs(last.x - x); const dy = -C.abs(last.y - y); const sx: i64 = if (x < last.x) 1 else -1; const sy: i64 = if (y < last.y) 1 else -1; var error_value = dx + dy; var result: std.ArrayList(C.Point) = .empty;
    while (true) { C.push(C.Point, &result, .{ .x = x, .y = y }); if (x == last.x and y == last.y) return result.items; const doubled = 2 * error_value; if (doubled >= dy) { error_value += dy; x += sx; } if (doubled <= dx) { error_value += dx; y += sy; } }
}
pub fn expand(mask: C.Mask, point: C.Point, width: i64, clip: C.Rect) void { const low = -@divFloor(width - 1, 2); var dy = low; while (dy < low + width) : (dy += 1) { var dx = low; while (dx < low + width) : (dx += 1) mask.add(.{ .x = point.x + dx, .y = point.y + dy }, clip); } }
pub fn circle(radius: i64) []const C.Point { var result: std.ArrayList(C.Point) = .empty; var a = radius; var b: i64 = 0; var error_value = 1 - radius; while (a >= b) { const points = [_]C.Point{ .{ .x = a, .y = b }, .{ .x = b, .y = a }, .{ .x = -b, .y = a }, .{ .x = -a, .y = b }, .{ .x = -a, .y = -b }, .{ .x = -b, .y = -a }, .{ .x = b, .y = -a }, .{ .x = a, .y = -b } }; for (points) |point| C.push(C.Point, &result, point); b += 1; if (error_value < 0) error_value += 2 * b + 1 else { a -= 1; error_value += 2 * (b - a) + 1; } } return result.items; }
fn quadrants(result: *std.ArrayList(C.Point), x: i64, y: i64) void { C.push(C.Point, result, .{ .x = x, .y = y }); C.push(C.Point, result, .{ .x = -x, .y = y }); C.push(C.Point, result, .{ .x = x, .y = -y }); C.push(C.Point, result, .{ .x = -x, .y = -y }); }
pub fn ellipse(rx: i64, ry: i64) []const C.Point { const rx2 = rx * rx; const ry2 = ry * ry; var x: i64 = 0; var y = ry; var result: std.ArrayList(C.Point) = .empty; C.push(C.Point, &result, .{ .x = 0, .y = ry }); C.push(C.Point, &result, .{ .x = 0, .y = -ry });
    while (ry2 * x < rx2 * y) { const decision = 4 * ry2 * (x + 1) * (x + 1) + rx2 * (2 * y - 1) * (2 * y - 1) - 4 * rx2 * ry2; x += 1; if (decision >= 0) y -= 1; quadrants(&result, x, y); }
    while (y > 0) { const decision = ry2 * (2 * x + 1) * (2 * x + 1) + 4 * rx2 * (y - 1) * (y - 1) - 4 * rx2 * ry2; y -= 1; if (decision <= 0) x += 1; quadrants(&result, x, y); } return result.items;
}
pub fn bezier(controls: []const C.Point, segments: usize) []const C.Point { const result = C.tempAlloc(C.Point, segments + 1); const s = C.int(segments); const degree = controls.len - 1; const scale = if (degree == 2) s * s else s * s * s; for (result, 0..) |*point, position| { const i = C.int(position); const rest = s - i; const weights: [4]i64 = if (degree == 2) .{ rest * rest, 2 * i * rest, i * i, 0 } else .{ rest * rest * rest, 3 * i * rest * rest, 3 * i * i * rest, i * i * i }; var x: i64 = 0; var y: i64 = 0; for (controls, weights[0..controls.len]) |control, weight| { x += control.x * weight; y += control.y * weight; } point.* = .{ .x = C.roundRatio(x, scale), .y = C.roundRatio(y, scale) }; } return result; }
